 /** Translate presentation text only after WordPress starts initialization.
  * Early settings reads need raw defaults without initiating language loading.
  * @param string $message English interface message.
  * @return string Translated label after init, otherwise the source label.
  */
 private static function text( string $message ): string { return did_action( 'init' ) ? __( $message, 'site-essentials' ) : $message; }

